# which's build system comes from the cwm4 submodule. Its bootstrap asks
# git for the submodules that carry a configure.m4 (m4/submodules.m4);
# neither cwm4 nor indent does, so the file is written here and the copy
# needs no git. autogen.sh exits 0 when a tool is missing: configure is
# checked. The man page is made from which.texi by texinfo2man (from the
# indent submodule) and version.texi by automake, both only in maintainer
# mode, so a throwaway maintainer configure makes them, as for a release.

prep() {
  printf '%s\n\n%s\n' \
    '# This file is automatically generated by autogen.sh. Any changes will be overwritten!' \
    'AC_SUBST([CW_SUBDIRS], [""])' > m4/submodules.m4
  ./autogen.sh
  [[ -f configure ]] || { echo "which: autogen.sh did not generate configure" >&2; exit 1; }

  mkdir _maint
  (cd _maint && ../configure --enable-maintainer-mode && make which.1 version.texi && cp which.1 ..)
  rm -rf _maint
}
